import{_ as i,o as a,c as e,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const k=JSON.parse('{"title":"实时调度：SCHED_FIFO / RR / EDF","description":"","frontmatter":{},"headers":[],"relativePath":"os/sched/rt.md","filePath":"os/sched/rt.md","lastUpdated":1788475713000}'),n={name:"os/sched/rt.md"};function l(p,s,h,r,o,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="实时调度-sched-fifo-rr-edf" tabindex="-1">实时调度：SCHED_FIFO / RR / EDF <a class="header-anchor" href="#实时调度-sched-fifo-rr-edf" aria-label="Permalink to &quot;实时调度：SCHED_FIFO / RR / EDF&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>CFS / EEVDF 是 <strong>尽力而为</strong> 调度，没硬延迟保证. 工业 / 安全 / 媒体 / 控制系统有更严的要求:<strong>必须 K 个可调度任务每 100 μs 内 ack 完成一次</strong>, 必须把抖动盯死在硬指标上. 这就是 real-time scheduling 存在的意义. 这一章把 Linux 的 SCHED_FIFO / SCHED_RR / SCHED_DEADLINE 三个实时类拆开看，再讲业界控制领域使用的 EDF (Earliest Deadline First) — 实时抽象把它带回到硬件层 (看 ARM Cortex-R / 安全岛 automotive).</p><h2 id="_1-sched-fifo-sched-rr-posix-实时类" tabindex="-1">1. SCHED_FIFO / SCHED_RR：POSIX 实时类 <a class="header-anchor" href="#_1-sched-fifo-sched-rr-posix-实时类" aria-label="Permalink to &quot;1. SCHED_FIFO / SCHED_RR：POSIX 实时类&quot;">​</a></h2><p>Linux 把调度类按 priority 排叠:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[实时类 0-99] → 优先于 [CFS / EEVDF]</span></span></code></pre></div><p>两个 rt 类:</p><ul><li>SCHED_FIFO: FIFO 顺序, 跑到自愿让出;</li><li>SCHED_RR: 同 FIFO 但时间片 = 100 ms 后抢;</li></ul><p>进入配 rt priority 也能跨核 migration, 但 FIFO 是 panic-level &quot;不再被迫让位&quot;: 1 个 SCHED_FIFO 99 thread 跑 while(1) infinite ⇒ 其他线程全饿死. <strong>Linux 没默认 watchdog over FIFO thread</strong>.</p><h2 id="_2-sched-deadline-linux-edf-policy-引入" tabindex="-1">2. SCHED_DEADLINE：Linux EDF policy 引入 <a class="header-anchor" href="#_2-sched-deadline-linux-edf-policy-引入" aria-label="Permalink to &quot;2. SCHED_DEADLINE：Linux EDF policy 引入&quot;">​</a></h2><p>Linux 3.14+ 引入 SCHED_DEADLINE（基于 EDF 算法）. <strong>EDF</strong> (Earliest Deadline First):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每任务的三元组 (runtime, period, deadline):</span></span>
<span class="line"><span>  每周期 period 内, 须够 runtime μs CPU, 期限 deadline μs.</span></span></code></pre></div><p>Example: 任务 A (10 ms runtime, 100 ms period, 50 ms deadline):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每 100 ms 开始: 任务 A 必须在 deadline 50 ms 内跑完 10 ms CPU.</span></span>
<span class="line"><span>EDF: 每次调度只要流内 runtime &lt; deadline 的 task (内 runnable 中最早 dl 优先)</span></span></code></pre></div><p>调度器在 admit 时用 utilization check:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Σ (runtime_i / period_i) ≤ min(1, total_cores)</span></span></code></pre></div><p>单调 EDF 是最低可行算法 CPU utilization 上界 (Liu &amp; Layland 1973). SCHED_DEADLINE 是 Linux 给硬实时打 的 framework.</p><h2 id="_3-preempt-rt-kernel-自己-rt-化" tabindex="-1">3. PREEMPT_RT: kernel 自己 rt 化 <a class="header-anchor" href="#_3-preempt-rt-kernel-自己-rt-化" aria-label="Permalink to &quot;3. PREEMPT_RT: kernel 自己 rt 化&quot;">​</a></h2><p>Linux 默认不少 critical section (e.g. spinlock) 还不可抢占. PREEMPT_RT 是主支工程, kernel spinlock 换 raw_spinlock + rt_mutex + rcu_rrn 等让&quot; kernel 自己 rt friendly&quot;. PREEMPT_RT 已经渐进 mainline 多年并在 Linux 6.12 后全部 upstream.</p><p>打开 PREEMPT_RT 后:</p><ul><li>spinlock 改 rt mutex, 不能 thread 抢死; -IRQSOFT聋DDevice handler 变成 kernel thread (ksoftirqd);</li><li>大多数关键 path preempt-safe ⇒ max latency ~ 100 μs (默认 10 ms+).</li></ul><p>PREMPT_RT 用例: automotive (electric vehicle 中 BlueZ, ROS), industrial control, audio lowest latency.</p><h2 id="_4-real-time-延迟常数" tabindex="-1">4. Real-time 延迟常数 <a class="header-anchor" href="#_4-real-time-延迟常数" aria-label="Permalink to &quot;4. Real-time 延迟常数&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CFS (stock kernel): 50 μs -&gt; SECENDUST script best-but-p99 ~ 10 ms;</span></span>
<span class="line"><span>PREEMPT_RT kernel: ~ 100 μs p99 ~ 200 μs 配 CPU isolation;</span></span>
<span class="line"><span>PREMPT_RT + CPU isolation (isolcpus + nohz_full): ~ 20 μs p99;</span></span>
<span class="line"><span>Xenomai / RTAI co-kernel: &lt; 5 μs;</span></span>
<span class="line"><span>ARM Cortex-R / FPGA 双核 RT: &lt; 1 μs.</span></span></code></pre></div><p>工业 automotive sensor fusion / motor control 设置一般要 &lt; 100 μs. Linux PREEMPT_RT 可达成. 1 μs 级要 FPGA co-processor / Cortex-R.</p><h2 id="_5-时延抖动来源" tabindex="-1">5. 时延抖动来源 <a class="header-anchor" href="#_5-时延抖动来源" aria-label="Permalink to &quot;5. 时延抖动来源&quot;">​</a></h2><p>1.irq 创建 periodic timer tick; 2. tabnentiated m -burst time latch (CPU isolation). 3. spinlock hold time; 4.smp guest VM hypervisor exit cost; 5.内存管理 hot path cache miss / swap-in; 6.GPUAdditionally resource scheduler.</p><p>工程通过将实时任务<strong>完全无中断跑</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>isolcpus=2-3      # 在 boot 让 CPU 2-3 不接 irq, 永不会被 scan balance</span></span>
<span class="line"><span>nohz_full=2-3     # 不定时 tick</span></span>
<span class="line"><span>rcu_nocbs=2-3     # RCU callback 不在这 CPU</span></span>
<span class="line"><span>tuned-adm profile realtime</span></span>
<span class="line"><span>preempt=full</span></span></code></pre></div><p>process 上:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chrt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 99</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my_realtime_task</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chrt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./sdl_task</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # SCHED_DEADLINE 10 ms / 100 ms</span></span></code></pre></div><p>CPU affinity:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cpu_set_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> set;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CPU_ZERO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CPU_SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pthread_setaffinity_np</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pthread_self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(set), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="_6-arm-cortex-r-调度器硬件最后形态" tabindex="-1">6. ARM Cortex-R / 调度器硬件最后形态 <a class="header-anchor" href="#_6-arm-cortex-r-调度器硬件最后形态" aria-label="Permalink to &quot;6. ARM Cortex-R / 调度器硬件最后形态&quot;">​</a></h2><p>车规 / electrical 调速控电磁机 &lt; 1 μs 延迟不能轮. ARM Cortex-R / RISC-V 上的 MT (motor timer) ISR Direct interrupt classification &lt; 100 ns open + deliver to register to rt5 chip actuator. 这是 Linux PREEMPT_RT 击退卸交硬件 RT core.</p><p>代码模式:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 裸金属 Cortex-R 上</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__attribute__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">interrupt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;IRQ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> timer_handler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // bare-metal handler</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>eBPF + 嵌入式 Linux 用 BLabs + 专用 RT core. Sisoft follow 上 hardware RT 类同构 = 抽象在硬件层就是&quot;timer ISR 直接跑 with 跟 lane bandwidth&quot;.</p><h2 id="_7-这章带走的东西" tabindex="-1">7. 这章带走的东西 <a class="header-anchor" href="#_7-这章带走的东西" aria-label="Permalink to &quot;7. 这章带走的东西&quot;">​</a></h2><ul><li>SCHED_FIFO/RR 是有危险可饿死, 须小心;</li><li>SCHED_DEADLINE 基于 EDF + utilization 健康 check;</li><li>PREEMPT_RT 让 Linux kernel RT, 自 Linux 6.12+ mainline;</li><li>配 CPU isolation + nohz_full 时 接 &lt; 100 μs;</li><li>真硬 &lt; 1 μs RT 只能 Cortex-R / FPGA co-processor / Xenomai.</li></ul><p>下一节 → <a href="./gmp">GMP 模型</a></p>`,41)])])}const E=i(n,[["render",l]]);export{k as __pageData,E as default};
